/**
 * Attach the drawn placeholder artwork.
 *
 * Everything under public/placeholders is original illustration generated by
 * tools/artwork — no third party's photography and no other manufacturer's
 * branding. It is placeholder work: the point is that the catalogue reads as
 * one designed set until the client's own photographs replace it, product by
 * product, through /admin.
 *
 * Idempotent. Run `npm run placeholders:off` to strip the whole set and fall
 * back to the designed "photograph pending" plates.
 */
import { PrismaClient } from '@prisma/client';
import { existsSync } from 'node:fs';

const db = new PrismaClient();

async function main() {
  const cleared = await db.productImage.deleteMany({
    where: { url: { startsWith: '/placeholders/' } },
  });

  let products = 0;
  for (const p of await db.product.findMany()) {
    const url = `/placeholders/product-${p.slug}.jpg`;
    if (!existsSync(`public${url}`)) {
      console.log(`  no artwork for product ${p.slug}`);
      continue;
    }
    const existing = await db.productImage.count({ where: { productId: p.id } });
    await db.productImage.create({
      data: {
        productId: p.id,
        url,
        alt: `${p.name} — illustrated placeholder, pending the client's own photography`,
        position: existing,
        isPrimary: existing === 0,
      },
    });
    products += 1;
  }

  let categories = 0;
  for (const c of await db.category.findMany()) {
    const url = `/placeholders/banner-${c.slug}.jpg`;
    if (!existsSync(`public${url}`)) {
      console.log(`  no banner for collection ${c.slug}`);
      continue;
    }
    await db.category.update({ where: { id: c.id }, data: { imageUrl: url } });
    categories += 1;
  }

  console.log(`cleared ${cleared.count} · attached ${products} products, ${categories} banners`);
  console.log(`products still without an image: ${await db.product.count({ where: { images: { none: {} } } })}`);
  await db.$disconnect();
}

main();
